{
  "name": "azure-key-vault-config-provider",
  "version": "1.0.0",
  "private": true,
  "description": "A cached application configuration provider backed by Azure Key Vault.",
  "type": "module",
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "start": "node dist/src/main.js",
    "demo": "npm run build && npm run start",
    "test": "npm run build && node dist/test/run-tests.js"
  },
  "dependencies": {
    "@azure/identity": "^4.13.2",
    "@azure/keyvault-secrets": "^4.11.2"
  },
  "devDependencies": {
    "@types/node": "^26.2.0",
    "typescript": "^7.0.2"
  }
}

file_contents.src\\configuration.ts:
import { ManagedIdentityCredential } from "@azure/identity";
import { SecretClient } from "@azure/keyvault-secrets";

export function createKeyVaultSecretClient(
  environment: NodeJS.ProcessEnv = process.env,
): SecretClient {
  const vaultUrl = environment.KEY_VAULT_URL;
  if (vaultUrl === undefined || vaultUrl.trim() === "") {
    throw new Error("KEY_VAULT_URL is required");
  }

  const parsedUrl = new URL(vaultUrl);
  if (parsedUrl.protocol !== "https:") {
    throw new Error("KEY_VAULT_URL must use HTTPS");
  }

  const clientId = environment.AZURE_CLIENT_ID?.trim();
  const credential =
    clientId === undefined || clientId === ""
      ? new ManagedIdentityCredential()
      : new ManagedIdentityCredential({ clientId });

  return new SecretClient(parsedUrl.toString(), credential);
}

